export const RU_GRAMMAR_FEATURES: GrammarFeature[] = [
  { key: 'Case', label: 'Case', values: { Nom: 'nominative', Gen: 'genitive', Dat: 'dative', Acc: 'accusative', Ins: 'instrumental', Prep: 'prepositional', Loc: 'locative (second prepositional)', Par: 'partitive', Voc: 'vocative' }, explain: 'Russian marks the job a noun does in its sentence with an ending. The nominative names who or what acts (Кошка спит, the cat sleeps); the genitive says of what or whose, and follows many numbers and negations (нет книги, there is no book); the dative gives the receiver (Я дал книгу брату, I gave the book to my brother); the accusative is the direct object (Я читаю книгу); the instrumental is the tool or means (пишу ручкой, I write with a pen); the prepositional is used only after prepositions such as о, в and на (о книге, about the book). A few nouns also have a second locative after в and на (в лесу, in the forest) or a partitive (чашка чаю, a cup of tea).' },
  { key: 'Number', label: 'Number', values: { Sing: 'singular', Plur: 'plural' }, explain: 'The ending also says whether there is one thing or several: книга is one book, книги are books (or the genitive of one book, so the ending alone can leave both open). Adjectives, participles and past-tense verbs agree with their noun in number.' },
  { key: 'Gender', label: 'Gender', values: { Masc: 'masculine', Fem: 'feminine', Neut: 'neuter' }, explain: 'Every Russian noun is masculine, feminine or neuter, and adjectives, participles and the past tense of verbs must match it: новый дом (a new house), новая книга (a new book), новое окно (a new window). The gender of a noun is usually clear from its ending in the dictionary form, and it is a fact of the word, not of one inflected form. There is no gender in the plural.' },
  { key: 'Animacy', label: 'Animacy', values: { Anim: 'animate', Inan: 'inanimate' }, explain: 'Russian treats people and animals (animate) differently from things (inanimate) in one place, the accusative. For an inanimate masculine noun the accusative looks like the nominative (Я вижу стол), for an animate one it looks like the genitive (Я вижу брата, I see my brother). The same split applies to the plural of every gender.' },
  { key: 'Person', label: 'Person', values: { '1': '1st person', '2': '2nd person', '3': '3rd person' }, explain: 'Verbs in the present (or the future of a perfective verb) show who is acting: я читаю (I read, first person), ты читаешь (you read, second person), он читает (he reads, third person). The past tense has no person; it shows gender and number instead (я читал, я читала).' },
  { key: 'Tense', label: 'Tense', values: { Pres: 'present', Past: 'past', Fut: 'future' }, explain: 'The past ends in -л (читал, читала, читали); the present belongs to imperfective verbs (читаю, I read or I am reading). A perfective verb has no present: its present-shaped forms mean the future (прочитаю, I will read it through). An imperfective verb makes the future with the helper быть and the infinitive (буду читать).' },
  { key: 'Mood', label: 'Mood', values: { Ind: 'indicative', Imp: 'imperative' }, explain: 'The indicative states a fact (Он читает), the imperative gives an order or a request (Читай! Читайте!). The imperative has only the second person, in the singular for one person and in the plural for several or for politeness. The conditional is made with the particle бы and the past tense (Я бы прочитал), not with a verb ending.' },
  { key: 'VerbForm', label: 'Verb form', values: { Fin: 'finite verb', Inf: 'infinitive', Part: 'participle', Conv: 'adverbial participle' }, explain: 'A finite verb has a person or a gender and number (читаю, читала). The infinitive is the dictionary form (читать). A participle works like an adjective and agrees with its noun (читающий мальчик, the boy who is reading; прочитанная книга, the book that was read). An adverbial participle works like an adverb and shows an action alongside the main one (читая, while reading; прочитав, having read).' },
  { key: 'Voice', label: 'Voice', values: { Act: 'active', Pass: 'passive' }, explain: 'The voice of a participle: the active participle describes the one who acts (читающий, the one who is reading; прочитавший, the one who has read), the passive one describes what is acted on (читаемый, being read; прочитанный, read). A reflexive verb in -ся can also be passive (Книга читается, the book is read).' },
  { key: 'Aspect', label: 'Aspect', values: { Imp: 'imperfective', Perf: 'perfective' }, explain: 'Almost every verb comes in two aspects, which are two separate dictionary words. The perfective presents the event as a single whole, usually with its result or limit (прочитать, to read it through); the imperfective presents it as a process, a repeated event or a simple fact (читать, to read, to be reading). The two are usually named together as a pair, with the imperfective first.' },
  { key: 'Degree', label: 'Degree', values: { Cmp: 'comparative', Sup: 'superlative' }, explain: 'The comparative says more: быстрее (faster), больше (more). It does not change for case or gender when it stands alone in a sentence (Он быстрее меня, he is faster than me). The superlative is formed with самый or with the ending -ейший (самый быстрый, the fastest).' },
  { key: 'Variant', label: 'Form variant', values: { Short: 'short form' }, explain: 'Many adjectives and passive participles have a short form that changes only for gender and number and is used after a noun in the predicate: Книга интересна (the book is interesting), Дом построен (the house is built). The long form (интересная книга) is the one that takes the case endings.' },
  { key: 'Reflex', label: 'Reflexive', values: { Yes: 'reflexive' }, explain: 'A reflexive verb ends in -ся or -сь (мыться, to wash oneself; учиться, to study) and the action returns to the one who does it, or the verb simply has no object. The pronoun себя (oneself) is the reflexive pronoun and does not have a nominative case.' },
];

export const RU_GRAMMAR_CONSTRUCTIONS: GrammarConstruction[] = [
  { id: 'possession-u-est', label: 'Possession: у + genitive (+ есть)', explain: 'Russian has no verb "to have" for ordinary possession. It says "by me there is a book": у меня есть книга. The owner is in the genitive after у, the thing owned is the grammatical subject, and есть is often left out in speech. In the past or future the verb is быть: у меня была книга.' },
  { id: 'genitive-of-negation', label: 'Genitive of negation: нет / не было + genitive', explain: 'After нет (there is not), не было or не будет, the thing that is absent is in the genitive: у меня нет книги (I have no book), в комнате не было окон. Compare the affirmative у меня есть книга, where it is nominative.' },
  { id: 'past-perfective', label: 'Perfective past', explain: 'A perfective past presents one completed event as a whole, often with its result or as a step in a sequence: Она прочитала книгу (she read the book through). The past tense agrees with the subject in gender and number, not in person.' },
  { id: 'past-imperfective', label: 'Imperfective past', explain: 'An imperfective past presents a process, a repeated or habitual action, or the plain fact that something happened: Она читала книгу (she was reading / used to read the book). The past tense agrees with the subject in gender and number.' },
  { id: 'future-perfective', label: 'Perfective future (present-shaped)', explain: 'A perfective verb has no present tense: its present-shaped form means the future: Я прочитаю книгу (I will read the book). The same endings as the present of an imperfective verb, but a different meaning.' },
  { id: 'future-imperfective', label: 'Imperfective future: буду + infinitive', explain: 'The imperfective future is made with the future of быть and an imperfective infinitive: Я буду читать (I will be reading / I will read). Only imperfective verbs make their future this way.' },
  { id: 'conditional-by', label: 'Conditional: бы + past', explain: 'The particle бы with a past-tense verb makes the conditional or a polite wish: Я бы прочитал эту книгу (I would read this book). Бы can stand after the verb or after another word of the clause; the verb ends as a past tense does, in gender and number.' },
  { id: 'imperative', label: 'Imperative', explain: 'The imperative addresses someone: Читай! (to a friend), Читайте! (to several people or politely). A perfective imperative asks for one concrete act (Прочитай эту страницу), an imperfective one for a process, a repeated act or a general invitation (Читай каждый день).' },
  { id: 'reflexive-verb', label: 'Reflexive verb: -ся / -сь', explain: 'The ending -ся (-сь after a vowel) marks a verb that is reflexive (мыться: to wash oneself), reciprocal (встречаться: to meet each other), intransitive or "middle" (начаться: to begin), or the passive of an imperfective verb (строиться: to be built). It cannot take a direct object. The dictionary says which meanings a given verb has.' },
  { id: 'motion-determinate', label: 'Verb of motion: determinate', explain: 'A determinate verb of motion (идти, ехать, бежать, лететь …) describes one trip in one direction, at one moment: Я иду в школу (I am on my way to school). Its indeterminate partner (ходить, ездить …) is used for habits and round trips.' },
  { id: 'motion-indeterminate', label: 'Verb of motion: indeterminate', explain: 'An indeterminate verb of motion (ходить, ездить, бегать, летать …) describes a habit, a round trip, movement with no single goal, or an ability: Я хожу в школу каждый день. Its determinate partner (идти, ехать …) is used for one trip in one direction.' },
  { id: 'motion-prefixed', label: 'Prefixed verb of motion', explain: 'A prefix on a verb of motion adds the direction: при- arrival, у- leaving, в- into, вы- out of. Built on the determinate stem the verb is perfective (прийти: to arrive); its imperfective partner is built on the indeterminate stem (приходить). Он пришёл домой: he came home.' },
  { id: 'numeral-noun', label: 'Numeral + noun: genitive', explain: 'After два, три, четыре the noun is genitive singular (два года); after пять and higher numbers, and after много, мало, несколько, сколько, it is genitive plural (пять лет, много людей). After один the noun agrees in case (один год).' },
  { id: 'instrumental-predicate', label: 'Instrumental predicate: быть / стать + instrumental', explain: 'With быть (in the past or future), стать, являться, казаться or оказаться, the noun or adjective that says what the subject is or becomes is in the instrumental: Он был врачом (he was a doctor), Она стала учительницей. In the present tense быть is left out and the predicate is nominative: Он врач.' },
  { id: 'dative-experiencer', label: 'Dative experiencer: мне нравится, мне холодно', explain: 'To say how someone feels or what someone likes, Russian puts the person in the dative: Мне нравится эта книга (I like this book; literally: to me is pleasing), Мне холодно (I am cold), Мне нужно идти (I need to go).' },
  { id: 'impersonal-modal', label: 'Impersonal modal: можно, нужно, надо, нельзя + infinitive', explain: 'The words можно (one may), нужно and надо (one must), нельзя (one must not, it is impossible) are followed by an infinitive and need no subject: Здесь можно курить. The person, when named, is in the dative: Мне надо идти. Нельзя + imperfective infinitive forbids; нельзя + perfective says it cannot be done.' },
  { id: 'short-adjective', label: 'Short-form adjective as predicate', explain: 'A short adjective (рад, готов, должен, красива, открыты) stands after the noun as the predicate and agrees in gender and number: Она рада (she is glad), Окно открыто. Only the nominative exists, and many adjectives have a short form only in this use.' },
  { id: 'comparative', label: 'Comparative: чем or the genitive', explain: 'The thing compared with comes after чем (than) or, with no чем, in the genitive: Он старше, чем она; Он старше её (he is older than she). Больше, меньше, лучше, хуже, быстрее are comparatives.' },
  { id: 'participle-active', label: 'Active participle', explain: 'An active participle describes a noun by an action it does: читающий человек (the person who is reading), прочитавший книгу (who has read the book). It agrees with its noun like an adjective and comes from a verb; it is mostly written, not spoken, Russian.' },
  { id: 'participle-passive', label: 'Passive participle', explain: 'A passive participle describes a noun by an action done to it: прочитанная книга (the book that has been read), написанное письмо. The short form is a predicate: Письмо написано (the letter is written).' },
  { id: 'adverbial-participle', label: 'Adverbial participle', explain: 'An adverbial participle names a second action of the SAME subject as the main verb: Читая, он улыбался (while reading, he smiled; imperfective: at the same time) and Прочитав письмо, он ушёл (having read the letter, he left; perfective: before). It is set off by commas and never changes.' },
  { id: 'chtoby-infinitive', label: 'чтобы + infinitive: purpose', explain: 'Чтобы with an infinitive gives the purpose of an action of the same subject: Я пришёл, чтобы помочь (I came in order to help). When the subjects differ, чтобы is followed by a past-tense form: Я хочу, чтобы ты помог.' },
  { id: 'chtoby-past', label: 'чтобы + past: purpose or wish with a different subject', explain: 'Чтобы with a past-tense verb expresses a wish or purpose whose subject differs from the main clause: Я хочу, чтобы ты пришёл (I want you to come). The past form is not about the past: it is the subjunctive.' },
  { id: 'relative-kotoryj', label: 'Relative который', explain: 'Который (who, which, that) agrees with the noun it refers to in gender and number, but its CASE comes from its own clause: Книга, которую я читаю (the book that I am reading): which is feminine singular like книга, but accusative because it is the object of читаю.' },
  { id: 'preposition-direction', label: 'в / на / за / под + accusative: direction', explain: 'Some prepositions take two cases and the case changes the meaning. With the accusative they answer куда? (where to?): Я иду в школу, на работу, за дом. With the prepositional (в, на) or the instrumental (за, под) they answer где? (where?): Я в школе, на работе, за домом.' },
  { id: 'preposition-location', label: 'в / на + prepositional, за / под + instrumental: location', explain: 'Some prepositions take two cases and the case changes the meaning. With the prepositional (в, на) or the instrumental (за, под) they answer где? (where?): Я в школе, на работе, за домом. With the accusative they answer куда? (where to?): Я иду в школу.' },
];
